// Challenge 16: Monte Carlo Pricer (Rust) -- public benchmark
//
// The certified run uses the same code with options drawn from private seeds.

mod types;
#[path = "../solution/mod.rs"]
mod solution;
use hftu_bench::{self, black_box, clobber, cycle_end, cycle_start};
use types::{MCOption, MCResult, MonteCarloPricer};

const PATHS: i32 = 10_000;
const STEPS: i32 = 100;

// ---------------------------------------------------------------------------
// Validation: every result is compared with a reference price, in two ways.
//   1. Precision. The error, in units of the standard error a plain
//      10,000-path simulation would have, must stay within MAX_Z on every
//      option. An honest 10k-path simulation fails this about once in 4,000
//      runs; one with a quarter of the paths fails almost every time.
//   2. Honest error. The same, in units of the std_error the solution reports.
//      Variance reduction or any other method may report a smaller error, but
//      the price must then be that accurate.
// Both denominators include the reference's own standard error and an absolute
// floor, so options whose price is (near) zero cannot fail on rounding. There
// is no batch-average limit: reusing one set of paths for every option makes a
// batch's errors move together (see the C++ benchmark).
//
// The harness validates before it times, so a solution could tell the calls
// apart. The timed call's own output is therefore checked too, after every
// timed call and outside the timed window.
// ---------------------------------------------------------------------------

const MAX_Z: f64 = 5.0;
const PRICE_FLOOR: f64 = 1e-3;

/// One option and its reference price: Black-Scholes for Europeans (exact for
/// the 100-step model), else a 10M-path antithetic simulation of the
/// skeleton's model. `ref_se` is the reference's own standard error (0 for
/// Europeans), `se10k` that of a plain 10,000-path simulation.
#[derive(Clone, Copy)]
struct Reference {
    option: MCOption,
    price: f64,
    ref_se: f64,
    se10k: f64,
}

fn type_name(t: i32) -> &'static str {
    match t {
        0 => "European",
        1 => "Asian",
        2 => "up-and-out",
        3 => "down-and-out",
        _ => "unknown",
    }
}

fn nan_results(n: usize) -> Vec<MCResult> {
    vec![MCResult { price: f64::NAN, std_error: f64::NAN }; n]
}

fn report_option(test: &str, what: &str, unit: &str, r: &Reference, out: &MCResult, z: f64) {
    let o = &r.option;
    eprintln!(
        "FAIL [{}]: {}: {} {} S={:.6} K={:.6} B={:.6} r={:.6} vol={:.6} T={:.6} -> price {:.8}, std_error {:.8} (off by {:.1} {})",
        test, what, type_name(o.option_type), if o.is_call { "call" } else { "put" }, o.spot, o.strike,
        o.barrier, o.rate, o.vol, o.time_to_expiry, out.price, out.std_error, z.abs(), unit
    );
}

fn validate_batch(test: &str, refs: &[Reference], out: &[MCResult], report_pass: bool) -> bool {
    let (mut invalid, mut imprecise, mut overclaimed, mut checked) = (0usize, 0usize, 0usize, 0usize);
    let mut first_invalid: Option<usize> = None;
    let (mut worst_p, mut worst_c): (Option<(usize, f64)>, Option<(usize, f64)>) = (None, None);
    let (mut sum_zp2, mut sum_zc2) = (0.0f64, 0.0f64);

    for (i, (r, o)) in refs.iter().zip(out.iter()).enumerate() {
        if !o.price.is_finite() || !o.std_error.is_finite() || o.std_error < 0.0 {
            invalid += 1;
            first_invalid.get_or_insert(i);
            continue;
        }
        let err = o.price - r.price;
        let floor2 = r.ref_se * r.ref_se + PRICE_FLOOR * PRICE_FLOOR;
        let zp = err / (r.se10k * r.se10k + floor2).sqrt();
        let zc = err / (o.std_error * o.std_error + floor2).sqrt();
        checked += 1;
        sum_zp2 += zp * zp;
        sum_zc2 += zc * zc;
        if zp.abs() > MAX_Z { imprecise += 1; }
        if zc.abs() > MAX_Z { overclaimed += 1; }
        if worst_p.map_or(true, |(_, w)| zp.abs() > w.abs()) { worst_p = Some((i, zp)); }
        if worst_c.map_or(true, |(_, w)| zc.abs() > w.abs()) { worst_c = Some((i, zc)); }
    }

    let mut ok = true;
    if out.len() != refs.len() {
        eprintln!("FAIL [{}]: {} results for {} options", test, out.len(), refs.len());
        ok = false;
    }
    if let Some(i) = first_invalid {
        eprintln!(
            "FAIL [{}]: {} of {} results have a price or std_error that is not a finite number, or a negative std_error (first: option {}, price {}, std_error {})",
            test, invalid, refs.len(), i, out[i].price, out[i].std_error
        );
        ok = false;
    }
    if imprecise > 0 {
        eprintln!(
            "FAIL [{}]: prices are less precise than a 10,000-path simulation: {} of {} more than {:.0} standard errors from the reference",
            test, imprecise, checked, MAX_Z
        );
        if let Some((i, z)) = worst_p {
            report_option(test, "precision, worst case", "10k-path standard errors", &refs[i], &out[i], z);
        }
        ok = false;
    }
    if overclaimed > 0 {
        eprintln!(
            "FAIL [{}]: std_error understates the actual error: {} of {} prices more than {:.0} reported std_errors from the reference",
            test, overclaimed, checked, MAX_Z
        );
        if let Some((i, z)) = worst_c {
            report_option(test, "std_error, worst case", "reported std_errors", &refs[i], &out[i], z);
        }
        ok = false;
    }
    if ok && report_pass && checked > 0 {
        eprintln!(
            "  {}: {} prices checked, mean squared error {:.2} (10k-path SE) / {:.2} (own std_error)",
            test, checked, sum_zp2 / checked as f64, sum_zc2 / checked as f64
        );
    }
    ok
}

fn price_and_validate(test: &str, refs: &[Reference]) -> bool {
    let options: Vec<MCOption> = refs.iter().map(|r| r.option).collect();
    let mut results = nan_results(options.len());
    let mut pricer = solution::MyPricer::new();
    pricer.build(PATHS, STEPS);
    pricer.price_batch(&options, &mut results);
    validate_batch(test, refs, &results, true)
}

